    s_bottom = max(r for r, c in sixes)
    top_width = sum(r == s_top for r, c in sixes)
    bottom_width = sum(r == s_bottom for r, c in sixes)

    if top_width != bottom_width:
        # The T marker's stem direction selects the horizontal reflection side.
        left, right = min(c for r, c in fours), max(c for r, c in fours)
        if top_width > bottom_width:
            # Stem points down: reflect to the right.
            for r, c in fours:
                cc = 2 * right + 1 - c
                if 0 <= cc < w:
                    out[r][cc] = 4
        else:
            # Stem points up: reflect to the left.
            for r, c in fours:
                cc = 2 * left - 1 - c
                if 0 <= cc < w:
                    out[r][cc] = 4
    else:
        # Cross-like marker: reflect vertically, preferably away from the marker.
        top = min(r for r, c in fours)
        bottom = max(r for r, c in fours)
        marker_below = sum(r for r, c in sixes) / len(sixes) > sum(
            r for r, c in fours
        ) / len(fours)

        def fits(up):
            return all(0 <= (2 * top - 1 - r if up else 2 * bottom + 1 - r) < h
                       for r, c in fours)

        up = marker_below
        if not fits(up):
            up = not up
        for r, c in fours:
            rr = 2 * top - 1 - r if up else 2 * bottom + 1 - r
            if 0 <= rr < h:
                out[rr][c] = 4

